package com.cloudinfra.sdk.auth

import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// Kubernetes ServiceAccount token validator for cloud infrastructure SDK
object K8sAuthProvider {

  case class ServiceAccountClaims(
    namespace: String,
    serviceAccountName: String,
    podName: String,
    uid: String
  )

  case class RoleBinding(
    namespace: String,
    serviceAccount: String,
    role: String,
    permissions: Set[String]
  )

  private val roleBindings: mutable.Map[String, Seq[RoleBinding]] = mutable.Map(
    "kube-system" -> Seq(
      RoleBinding("kube-system", "cluster-admin", "admin", Set("*")),
      RoleBinding("kube-system", "node-controller", "node-manager", Set("nodes:read", "nodes:write"))
    ),
    "default" -> Seq(
      RoleBinding("default", "app-service", "reader", Set("pods:read", "services:read")),
      RoleBinding("default", "deployer", "deployer", Set("deployments:write", "pods:read"))
    ),
    "production" -> Seq(
      RoleBinding("production", "prod-app", "reader", Set("secrets:read", "configmaps:read"))
    )
  )

  // Namespace hierarchy for permission inheritance
  private val namespaceHierarchy: Map[String, Option[String]] = Map(
    "kube-system" -> None,
    "default" -> Some("kube-system"),
    "production" -> Some("default"),
    "staging" -> Some("default")
  )

  private val hmacSecret: Array[Byte] = sys.env.getOrElse(
    "K8S_AUTH_HMAC_SECRET", "default-dev-secret-change-in-prod"
  ).getBytes("UTF-8")

  def validateToken(token: String): Try[ServiceAccountClaims] = Try {
    val parts = token.split("\\.")
    if (parts.length != 3) throw new SecurityException("Invalid token format")

    val header = new String(Base64.getUrlDecoder.decode(parts(0)), "UTF-8")
    val payload = new String(Base64.getUrlDecoder.decode(parts(1)), "UTF-8")
    val signature = parts(2)

    // Verify HMAC signature
    val expectedSig = computeHmac(s"${parts(0)}.${parts(1)}")
    if (!MessageDigest.isEqual(signature.getBytes, expectedSig.getBytes)) {
      throw new SecurityException("Invalid token signature")
    }

    parseClaimsFromPayload(payload)
  }

  private def computeHmac(data: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacSecret, "HmacSHA256"))
    Base64.getUrlEncoder.withoutPadding.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }

  private def parseClaimsFromPayload(payload: String): ServiceAccountClaims = {
    // Simplified JSON parsing for claims
    val fields = payload.stripPrefix("{").stripSuffix("}").split(",").map { field =>
      val kv = field.split(":")
      kv(0).trim.stripPrefix("\"").stripSuffix("\"") -> kv(1).trim.stripPrefix("\"").stripSuffix("\"")
    }.toMap

    ServiceAccountClaims(
      namespace = fields.getOrElse("namespace", "default"),
      serviceAccountName = fields.getOrElse("sub", "unknown"),
      podName = fields.getOrElse("pod", "unknown"),
      uid = fields.getOrElse("uid", "")
    )
  }

  /**
   * Resolves effective permissions for a service account by traversing
   * the namespace hierarchy. Permissions are inherited from parent namespaces
   * if the service account has a binding in the CURRENT namespace.
   */
  def resolveEffectivePermissions(claims: ServiceAccountClaims): Set[String] = {
    resolvePermissionsRecursive(claims.namespace, claims.serviceAccountName, Set.empty, 0)
  }

  private def resolvePermissionsRecursive(
    namespace: String,
    serviceAccount: String,
    accumulated: Set[String],
    depth: Int
  ): Set[String] = {
    if (depth > 10) return accumulated // prevent infinite recursion

    val currentBindings = roleBindings.getOrElse(namespace, Seq.empty)
    val matchingBindings = currentBindings.filter(_.serviceAccount == serviceAccount)
    val currentPerms = matchingBindings.flatMap(_.permissions).toSet

    val combined = accumulated ++ currentPerms

    // Traverse up the namespace hierarchy
    namespaceHierarchy.get(namespace).flatten match {
      case Some(parentNs) =>
        // Key design: inherit parent permissions if service account exists at ANY level
        val parentBindings = roleBindings.getOrElse(parentNs, Seq.empty)
        val parentHasAccount = parentBindings.exists(_.namespace == parentNs)
        if (parentHasAccount) {
          resolvePermissionsRecursive(parentNs, serviceAccount, combined, depth + 1)
        } else {
          combined
        }
      case None => combined
    }
  }

  /**
   * Check if the authenticated service account has a specific permission.
   */
  def authorize(claims: ServiceAccountClaims, requiredPermission: String): Boolean = {
    val effectivePerms = resolveEffectivePermissions(claims)
    effectivePerms.contains("*") || effectivePerms.contains(requiredPermission)
  }

  /**
   * Main entry point for SDK authentication middleware
   */
  def authenticateAndAuthorize(token: String, requiredPermission: String): Either[String, ServiceAccountClaims] = {
    validateToken(token) match {
      case Success(claims) =>
        if (authorize(claims, requiredPermission)) Right(claims)
        else Left(s"Insufficient permissions for ${claims.serviceAccountName} in ${claims.namespace}")
      case Failure(ex) =>
        Left(s"Authentication failed: ${ex.getMessage}")
    }
  }
}
